#include "DeadlockPanel.h"
#include "StateIO.h"
#include <imgui.h>
#include <algorithm>
#include <cmath>
#include <fstream>
#include <sstream>

namespace minios::gui {
DeadlockPanel::DeadlockPanel(){reset();}
void DeadlockPanel::loadBanker(int i){
 if(i==0){n_=5;m_=3;alloc_={{0,1,0},{2,0,0},{3,0,2},{2,1,1},{0,0,2}};max_={{7,5,3},{3,2,2},{9,0,2},{2,2,2},{4,3,3}};avail_={3,3,2};}
 else if(i==1){n_=3;m_=3;alloc_={{1,0,1},{1,1,0},{0,1,1}};max_={{2,1,1},{1,2,1},{1,1,2}};avail_={1,1,0};}
 else{n_=3;m_=2;alloc_={{1,0},{0,1},{1,1}};max_={{2,2},{1,2},{3,1}};avail_={0,0};}
 request_.assign(m_,0);requestPid_=std::min(1,n_-1);runSafety();
}
void DeadlockPanel::reset(){loadBanker(0);loadGraph(true);status_="Loaded textbook Banker example";}
void DeadlockPanel::runSafety(){try{safety_=Deadlock::safety(alloc_,max_,avail_);error_.clear();playback_.reset();status_=safety_.safe?"State is safe":"State is unsafe";}catch(const std::exception&e){error_=e.what();}}
void DeadlockPanel::runRequest(){try{requestResult_=Deadlock::request(alloc_,max_,avail_,requestPid_,request_);status_=requestResult_.explanation;}catch(const std::exception&e){error_=e.what();}}
void DeadlockPanel::exportResults(){std::ofstream f("deadlock_results.txt");f<<(safety_.safe?"SAFE\nSequence: ":"UNSAFE\n");for(int p:safety_.sequence)f<<'P'<<p<<' ';f<<"\nNeed matrix:\n";for(const auto&row:safety_.need){for(int x:row)f<<x<<' ';f<<'\n';}f<<"\nGraph cycle: "<<(cycle_.hasCycle?"yes":"no")<<"\n";for(int p:cycle_.deadlockedProcesses)if(p<graphProcesses_)f<<'P'<<p<<' ';status_=f?"Saved deadlock_results.txt":"Export failed";}
std::string DeadlockPanel::saveState()const{std::vector<int>a,x;for(const auto&row:alloc_)a.insert(a.end(),row.begin(),row.end());for(const auto&row:max_)x.insert(x.end(),row.begin(),row.end());std::ostringstream o;o<<"{\"n\":"<<n_<<",\"m\":"<<m_<<",\"allocation\":"<<stateio::list(a)<<",\"maximum\":"<<stateio::list(x)<<",\"available\":"<<stateio::list(avail_)<<'}';return o.str();}
bool DeadlockPanel::loadState(const std::string&json){int n=stateio::integer(json,"n",0),m=stateio::integer(json,"m",0);auto a=stateio::array(json,"allocation"),x=stateio::array(json,"maximum"),v=stateio::array(json,"available");if(n<=0||m<=0||a.size()!=(size_t)n*m||x.size()!=(size_t)n*m||v.size()!=(size_t)m)return false;n_=n;m_=m;alloc_.assign(n_,std::vector<int>(m_));max_.assign(n_,std::vector<int>(m_));for(int i=0;i<n_;++i)for(int j=0;j<m_;++j){alloc_[i][j]=a[i*m_+j];max_[i][j]=x[i*m_+j];}avail_=v;request_.assign(m_,0);requestPid_=0;runSafety();return error_.empty();}
void DeadlockPanel::loadGraph(bool dead){graphProcesses_=4;graphResources_=2;edges_=dead?std::vector<GraphEdge>{{0,4},{4,1},{1,5},{5,0}}:std::vector<GraphEdge>{{0,4},{4,1},{2,5}};positions_.clear();for(int i=0;i<graphProcesses_;++i)positions_.push_back({90.0f+i*115.0f,90.0f});for(int i=0;i<graphResources_;++i)positions_.push_back({150.0f+i*220.0f,240.0f});cycle_=Deadlock::detectCycle(graphProcesses_+graphResources_,edges_);status_=dead?"Loaded deadlocked RAG":"Loaded safe RAG";}
static void matrixEditor(const char*id,std::vector<std::vector<int>>&mat,int n,int m){if(ImGui::BeginTable(id,m+1,ImGuiTableFlags_Borders|ImGuiTableFlags_SizingFixedFit)){ImGui::TableSetupColumn("");for(int j=0;j<m;++j)ImGui::TableSetupColumn(("R"+std::to_string(j)).c_str());ImGui::TableHeadersRow();for(int i=0;i<n;++i){ImGui::TableNextRow();ImGui::TableNextColumn();ImGui::Text("P%d",i);for(int j=0;j<m;++j){ImGui::TableNextColumn();ImGui::PushID(i*100+j);ImGui::SetNextItemWidth(45);ImGui::InputInt("##v",&mat[i][j],0,0);ImGui::PopID();}}ImGui::EndTable();}}
void DeadlockPanel::drawGraph(){ImVec2 canvas=ImGui::GetCursorScreenPos(),size(ImGui::GetContentRegionAvail().x,340);ImGui::InvisibleButton("ragcanvas",size,ImGuiButtonFlags_MouseButtonLeft);auto*dl=ImGui::GetWindowDrawList();dl->AddRectFilled(canvas,canvas+size,IM_COL32(28,31,38,255),5);if(ImGui::IsItemHovered()&&ImGui::IsMouseDragging(ImGuiMouseButton_Left)){ImVec2 mouse=ImGui::GetIO().MousePos;for(auto&pos:positions_){ImVec2 q=canvas+pos;if(std::hypot(mouse.x-q.x,mouse.y-q.y)<28){pos=mouse-canvas;break;}}}
 auto inCycle=[&](int a,int b){for(size_t i=1;i<cycle_.cycle.size();++i)if(cycle_.cycle[i-1]==a&&cycle_.cycle[i]==b)return true;return false;};for(auto e:edges_){if(e.from>=(int)positions_.size()||e.to>=(int)positions_.size())continue;ImVec2 a=canvas+positions_[e.from],b=canvas+positions_[e.to];ImVec2 delta=b-a;float len=std::max(1.0f,std::hypot(delta.x,delta.y));ImVec2 unit(delta.x/len,delta.y/len),end=b-unit*27.0f;ImU32 col=inCycle(e.from,e.to)?IM_COL32(255,65,65,255):(e.from<graphProcesses_?IM_COL32(255,180,55,255):IM_COL32(70,180,245,255));dl->AddLine(a,end,col,3);ImVec2 side(-unit.y,unit.x);dl->AddTriangleFilled(end,end-unit*12.0f+side*6.0f,end-unit*12.0f-side*6.0f,col);}
 for(int i=0;i<(int)positions_.size();++i){ImVec2 q=canvas+positions_[i];bool red=std::find(cycle_.cycle.begin(),cycle_.cycle.end(),i)!=cycle_.cycle.end();ImU32 col=red?IM_COL32(210,55,55,255):colorFor(i);if(i<graphProcesses_)dl->AddCircleFilled(q,25,col);else dl->AddRectFilled(q-ImVec2(25,25),q+ImVec2(25,25),col,3);std::string s=i<graphProcesses_?"P"+std::to_string(i):"R"+std::to_string(i-graphProcesses_);ImVec2 ts=ImGui::CalcTextSize(s.c_str());dl->AddText(q-ts*.5f,IM_COL32_WHITE,s.c_str());}}
void DeadlockPanel::render(){if(ImGui::BeginTabBar("deadlock_parts")){if(ImGui::BeginTabItem("Banker's Avoidance")){ImGui::BeginChild("bank_left",{430,0},true);static int ex=0;const char*examples[]={"Classic safe","Small safe","Unsafe"};if(ImGui::Combo("Example",&ex,examples,3))loadBanker(ex);ImGui::Text("Allocation");matrixEditor("allocmat",alloc_,n_,m_);ImGui::Text("Maximum");matrixEditor("maxmat",max_,n_,m_);ImGui::Text("Available");for(int j=0;j<m_;++j){ImGui::PushID(j);ImGui::SetNextItemWidth(55);ImGui::InputInt("##av",&avail_[j],0,0);ImGui::SameLine();ImGui::Text("R%d",j);if(j+1<m_)ImGui::SameLine();ImGui::PopID();}ImGui::NewLine();if(ImGui::Button("Run safety check"))runSafety();ImGui::SameLine();if(ImGui::Button("Save Results"))exportResults();if(!error_.empty())ImGui::TextColored({1,.3f,.3f,1},"%s",error_.c_str());ImGui::Separator();ImGui::TextUnformatted("Resource request");ImGui::SliderInt("Process",&requestPid_,0,n_-1);for(int j=0;j<m_;++j){ImGui::PushID(1000+j);ImGui::SetNextItemWidth(55);ImGui::InputInt("##req",&request_[j],0,0);if(j+1<m_)ImGui::SameLine();ImGui::PopID();}if(ImGui::Button("Evaluate request"))runRequest();if(!requestResult_.explanation.empty())ImGui::TextWrapped("%s",requestResult_.explanation.c_str());ImGui::EndChild();ImGui::SameLine();
 ImGui::BeginChild("bank_main",{0,0},true);playbackControls("bank",playback_,safety_.steps.size());if(ImGui::BeginTable("need",m_+1,ImGuiTableFlags_Borders)){ImGui::TableSetupColumn("Need");for(int j=0;j<m_;++j)ImGui::TableSetupColumn(("R"+std::to_string(j)).c_str());ImGui::TableHeadersRow();for(int i=0;i<n_;++i){ImGui::TableNextRow();ImGui::TableNextColumn();ImGui::Text("P%d",i);for(int j=0;j<m_;++j){ImGui::TableNextColumn();ImGui::Text("%d",safety_.need[i][j]);}}ImGui::EndTable();}if(!safety_.steps.empty()){auto&s=safety_.steps[std::min(playback_.step,safety_.steps.size()-1)];ImGui::Text("Work:");ImGui::SameLine();for(int x:s.work){ImGui::Text("%d",x);ImGui::SameLine();}ImGui::NewLine();ImGui::TextWrapped("%s",s.note.c_str());ImGui::Text("Finish flags:");ImGui::SameLine();for(int i=0;i<n_;++i){ImGui::TextColored(s.finish[i]?ImVec4(.3f,1,.4f,1):ImVec4(1,.4f,.4f,1),"P%d:%c",i,s.finish[i]?'T':'F');ImGui::SameLine();}ImGui::NewLine();}if(safety_.safe){ImGui::TextColored({.3f,1,.4f,1},"SAFE sequence:");ImGui::SameLine();for(int p:safety_.sequence){ImGui::Text("P%d",p);ImGui::SameLine();}}else ImGui::TextColored({1,.3f,.3f,1},"UNSAFE");ImGui::EndChild();ImGui::EndTabItem();}
 if(ImGui::BeginTabItem("RAG / Detection")){if(ImGui::Button("Load deadlocked example"))loadGraph(true);ImGui::SameLine();if(ImGui::Button("Load safe example"))loadGraph(false);ImGui::SameLine();if(ImGui::Button("Add Process")){for(auto&e:edges_){if(e.from>=graphProcesses_)++e.from;if(e.to>=graphProcesses_)++e.to;}positions_.insert(positions_.begin()+graphProcesses_,{80.0f+graphProcesses_*50.0f,150.0f});++graphProcesses_;cycle_=Deadlock::detectCycle(graphProcesses_+graphResources_,edges_);}ImGui::SameLine();if(ImGui::Button("Add Resource")){++graphResources_;positions_.push_back({100.0f+graphResources_*80.0f,260.0f});}ImGui::SetNextItemWidth(100);ImGui::InputInt("From node",&edgeFrom_);ImGui::SameLine();ImGui::SetNextItemWidth(100);ImGui::InputInt("To node",&edgeTo_);ImGui::SameLine();if(ImGui::Button("Add Edge")){edges_.push_back({edgeFrom_,edgeTo_});cycle_=Deadlock::detectCycle(graphProcesses_+graphResources_,edges_);}ImGui::SameLine();if(ImGui::Button("Remove Edge")&&!edges_.empty()){edges_.pop_back();cycle_=Deadlock::detectCycle(graphProcesses_+graphResources_,edges_);}ImGui::TextDisabled("Node indices: processes 0..%d, resources %d..%d. Drag nodes. Orange=request, blue=assignment.",graphProcesses_-1,graphProcesses_,graphProcesses_+graphResources_-1);drawGraph();if(cycle_.hasCycle){ImGui::TextColored({1,.25f,.25f,1},"Cycle detected. Deadlocked processes:");ImGui::SameLine();for(int p:cycle_.deadlockedProcesses)if(p<graphProcesses_){ImGui::Text("P%d",p);ImGui::SameLine();}}else ImGui::TextColored({.3f,1,.4f,1},"No cycle detected.");ImGui::EndTabItem();}ImGui::EndTabBar();}}
} // namespace minios::gui
